"""Independent replay implementation (written from the spec) for differential testing."""
def sim(P,R,D,inp,slotsn,window,events):
    buf=[None]*slotsn
    sentv=[0]*P; acked=[0]*P; upnext=[0]*P; floor=0
    received=[[] for _ in range(P)]
    pend={}; created=0; ok=True
    estat=[]; ecrt=[]
    class E:
        __slots__=("seq","ranks","sum")
        def __init__(self,q):
            self.seq=q; self.ranks=set(); self.sum=[0]*D
    def mk(kind,rank,seq,value):
        nonlocal created
        if len(pend)>=2048 or created>=200000: raise RuntimeError("limit")
        p={"id":created,"kind":kind,"rank":rank,"seq":seq,"value":value}
        pend[created]=p; created+=1
        return created-1
    for ev in events:
        k=ev[0]; cr=[]
        if k=="send":
            r,q=ev[1],ev[2]
            hi=min(R, sentv[r]+window)
            if sentv[r]<=q<hi:
                cr.append(mk("up",r,q,[x for x in inp[r][q]])); st="ok"
            else: st="disabled"
        elif k=="retry":
            r=ev[1]
            ents=sorted([e.seq for e in buf if e is not None and len(e.ranks)==P and e.seq>=acked[r]])
            for q in ents:
                for e in buf:
                    if e is not None and e.seq==q:
                        cr.append(mk("down",r,q,[x for x in e.sum]))
            st="ok"
        elif k=="drop":
            if ev[1] in pend: del pend[ev[1]]; st="ok"
            else: st="missing"
        elif k=="duplicate":
            p=pend.get(ev[1])
            if p is None: st="missing"
            else:
                cr.append(mk(p["kind"],p["rank"],p["seq"],[x for x in p["value"]] if isinstance(p["value"],list) else p["value"]))
                st="ok"
        else:  # deliver
            p=pend.pop(ev[1],None)
            if p is None: st="missing"
            else:
                k2=p["kind"]; r=p["rank"]; q=p["seq"]
                if k2=="up":
                    if floor<=q<floor+slotsn:
                        i=q%slotsn; e=buf[i]
                        if e is None or e.seq!=q:
                            e=E(q); buf[i]=e
                        became=False
                        if r not in e.ranks:
                            s=e.sum
                            for j in range(D): s[j]+=p["value"][j]
                            e.ranks.add(r)
                            became = len(e.ranks)==P
                        n=upnext[r]
                        while True:
                            e2=buf[n%slotsn]
                            if e2 is not None and e2.seq==n and r in e2.ranks: n+=1
                            else: break
                        upnext[r]=n
                        cr.append(mk("uack",r,n,None))
                        if became:
                            for t in range(P):
                                cr.append(mk("down",t,q,[x for x in e.sum]))
                    else:
                        cr.append(mk("uack",r,upnext[r],None))
                elif k2=="uack":
                    if q>sentv[r]: sentv[r]=q
                elif k2=="down":
                    if q==len(received[r]): received[r].append([x for x in p["value"]])
                    cr.append(mk("dack",r,len(received[r]),None))
                else:
                    if q>acked[r]:
                        acked[r]=q
                        nf=min(acked)
                        if nf>floor:
                            floor=nf
                            for i in range(slotsn):
                                if buf[i] is not None and buf[i].seq<floor: buf[i]=None
                st="ok"
        estat.append(st); ecrt.append(cr)
    slotlist=sorted([{"seq":e.seq,"ranks":sorted(e.ranks),"sum":list(e.sum)} for e in buf if e is not None], key=lambda z: z["seq"])
    pks=[{"id":i,"kind":pend[i]["kind"],"rank":pend[i]["rank"],"seq":pend[i]["seq"],"value":pend[i]["value"]} for i in sorted(pend)]
    hosts=[{"sent":sentv[r],"received":[[x for x in v] for v in received[r]]} for r in range(P)]
    return {"hosts":hosts,"floor":floor,"slots":slotlist,"packets":pks,"events":[{"status":estat[i],"created":ecrt[i]} for i in range(len(events))]}
